using UnityEngine; namespace Mojinloop.Gameplay { public sealed class BackgroundScroller:MonoBehaviour { [SerializeField] Transform[] tiles; [SerializeField] float speed=2.2f,width=12.8f; public bool Scrolling{get;set;} public void Configure(Transform[] value,float valueSpeed,float tileWidth){tiles=value;speed=valueSpeed;width=tileWidth;} void Update(){if(!Scrolling||tiles==null)return;float d=speed*Time.unscaledDeltaTime;foreach(var tile in tiles){tile.position+=Vector3.left*d;if(tile.position.x<-width)tile.position+=Vector3.right*width*2f;}} } }
